  image_source_url = excluded.image_source_url,
  google_place_id = coalesce(excluded.google_place_id, public.activities.google_place_id),
  google_place_uri = coalesce(excluded.google_place_uri, public.activities.google_place_uri),
  google_rating = coalesce(excluded.google_rating, public.activities.google_rating),
